(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0021.js"] = [{"id":"glyph-seal-68a7","script":"seal","character":"梧","reading":"wú","description":"wú：〔～桐〕落叶乔木。木质轻而坚韧，可制乐器和各种器具，种子可食，亦可榨油。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梧"},{"id":"glyph-seal-68a8","script":"seal","character":"梨","reading":"lí","description":"lí：落叶乔木或灌木，果实是普通水果，品种很多～膏。广～。鸭～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梨"},{"id":"glyph-seal-68ad","script":"seal","character":"梭","reading":"suō","description":"suō：(1)织布时往返牵引纬线（横线）的工具，两头尖，中间粗，像枣核形～子（ａ．织布工具；ｂ．机关枪、冲锋枪的子弹夹子；ｃ．量词，如打了一～～子弹”）。\n(2)形状像梭的～镖。～子蟹。\n(3)喻不断地来往～巡。穿～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梭"},{"id":"glyph-seal-68af","script":"seal","character":"梯","reading":"tī","description":"tī：(1)登高用的器具、设备～子。楼～。木～。软～。电～。云～。阶～。\n(2)形状或作用像梯子的～田。～级。～形。～队（亦泛指工作中层层递补的力量）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梯"},{"id":"glyph-seal-68b0","script":"seal","character":"械","reading":"xiè","description":"xiè：(1)器物，家伙器～。机～。\n(2)武器～斗。军～。缴～投降。\n(3)木枷和镣铐之类的刑具～系。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-械"},{"id":"glyph-seal-68b3","script":"seal","character":"梳","reading":"shū","description":"shū：(1)整理头发的用具木～。角～。\n(2)用梳子整理头发～头。～洗（梳头洗脸）。～妆。～辫子（喻把纷繁的事项、问题等进行分析归类）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梳"},{"id":"glyph-seal-68b5","script":"seal","character":"梵","reading":"fàn","description":"fàn：关于古代印度的～语（印度古代的一种语言）。～文（印度古代的文字）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梵"},{"id":"glyph-seal-68bf","script":"seal","character":"梿","reading":"lián","description":"【梿枷】即\"连枷\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-梿"},{"id":"glyph-seal-68c0","script":"seal","character":"检","reading":"jiǎn","description":"法式,法度\n品行;节操\n约束,限制\n⒈查，查看，查验～字。～修。～收。\n⒉收敛，约束～点。言行失～。\n⒊法度，法则，方式定～。节奏同～。\n①仔细地查看。\n②查考。\n③检讨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-检"},{"id":"glyph-seal-68c1","script":"seal","character":"棁","reading":"tuō；zhuō","description":"zhuō：梁上的短柱。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棁"},{"id":"glyph-seal-68cb","script":"seal","character":"棋","reading":"qí","description":"qí：文娱项目的一类，亦特指棋子”象～。围～。～盘。～道。星罗～布。举～不定（喻拿不定主意）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棋"},{"id":"glyph-seal-68d5","script":"seal","character":"棕","reading":"zōng","description":"zōng：〔～榈〕常绿乔木，茎直立不分枝，叶大，木材可制器具，通称棕树”。\n〔～毛〕棕榈叶鞘的纤维，简称棕”，如～绳”，～绷”，～帚”，～编”。\n〔～熊〕哺乳动物，体大，毛棕褐色。掌和肉可食，皮可制皮褥，胆可入药。亦称马熊”、罴”；通称人熊”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棕"},{"id":"glyph-seal-68d8","script":"seal","character":"棘","reading":"jí","description":"jí：(1)酸枣树，茎上多刺；泛指有刺的苗木荆～。～手（喻事情难办）。～刺。～针。\n(2)针形的刺～皮动物。\n(3)古同戟”，兵器。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棘"},{"id":"glyph-seal-68da","script":"seal","character":"棚","reading":"péng","description":"péng：用竹木搭成架子，上面覆盖席、布等做成的遮蔽风雨日光的东西或简陋的小屋天～。帐～。窝～。～车。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棚"},{"id":"glyph-seal-68e0","script":"seal","character":"棠","reading":"táng","description":"táng：姓。\n〔～梨〕ａ．落叶乔木，果实略呈球形。可以用作嫁接各种梨的砧木；ｂ．这种植物的果实，均亦称杜梨”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棠"},{"id":"glyph-seal-68e3","script":"seal","character":"棣","reading":"dì；dài；tì","description":"dì：同弟”贤～。～友（兄弟友爱）。～鄂（喻兄弟友爱。亦作棣萼”）。\n〔～棠〕落叶灌木，花黄色。果实黑色，供观赏。\ndài：〔～～〕文雅安闲的样子，如威仪～～”。\ntì：通～通（通达，贯通）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棣"},{"id":"glyph-seal-68ee","script":"seal","character":"森","reading":"sēn","description":"sēn：(1)树木众多，引申为众多、繁盛～林。～立。～～。～然。～郁。\n(2)幽深可怕的样子阴～。～邃。\n(3)严整的样子～严。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-森"},{"id":"glyph-seal-68f0","script":"seal","character":"棰","reading":"chuí","description":"chuí：(1)短木棍一尺之～，日取其半，万世不竭”。\n(2)用棍子打，杖刑笞～暴国，齐一天下”。\n(3)鞭子，鞭打士以马～击亭长”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棰"},{"id":"glyph-seal-68f1","script":"seal","character":"棱","reading":"léng；lēng；líng","description":"léng：(1)物体上的条状突起，或不同方向的两个平面相连接的部分～角。瓦～。～椎（多面体的一种）。三～镜。模～两可。\n(2)神灵之威，威势威～。\nlēng：〔不～登〕口语赘词，用于某些形容词后，含厌恶意，如傻～～～”。\nlíng：〔穆～〕地名，在中国黑龙江省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棱"},{"id":"glyph-seal-68fa","script":"seal","character":"棺","reading":"guān","description":"guān：装殓死人的器具～材。～木。～椟。～椁。盖～论定。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棺"},{"id":"glyph-seal-68fc","script":"seal","character":"棼","reading":"fén","description":"fén：(1)纷乱治丝益～（整理丝不找头绪，越理越乱；喻做事没有条理）。\n(2)阁楼的栋～楣（栋梁）。\n(3)麻布素车～蔽”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-棼"},{"id":"glyph-seal-6905","script":"seal","character":"椅","reading":"yǐ；yī","description":"yǐ：有靠背的坐具～子。坐～。木～。躺～。\nyī：落叶乔木，木材可以制器物。亦称山桐子”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-椅"},{"id":"glyph-seal-690b","script":"seal","character":"椋","reading":"liáng","description":"liáng：〔～子木〕古书上说的一种树，亦称即来”、松杨”、灯台树”。\n〔～鸟〕鸟类的一科，喜群飞，食种子和昆虫，有的善于模仿别的鸟叫。如八哥”、鸥椋”等。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-椋"},{"id":"glyph-seal-690d","script":"seal","character":"植","reading":"zhí","description":"zhí：(1)栽种种～。培～。栽～。～树。\n(2)树立～立。～志（立志）。\n(3)戮住，竖起～耳。\n(4)生物的一大类，谷类、花草、树木等的统称～物。～被。～保。\n(5)古代军中监督工事的将官华元为～，巡功。”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-植"},{"id":"glyph-seal-690e","script":"seal","character":"椎","reading":"zhuī；chuí","description":"zhuī：构成高等动物背部中央骨柱的短骨～骨。脊～。颈～。胸～。尾～。\nchuí：(1)敲打东西的器具铁～。木～。鼓～。\n(2)敲打，用椎打击～鼓。～杀。～心泣血（形容极度悲痛的样子）。\n(3)愚钝，朴实～鲁。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-椎"},{"id":"glyph-seal-6910","script":"seal","character":"椐","reading":"jū；jv","description":"jū：古书上说的一种小树，有肿节，可以做手杖。\n〔～～〕相继的样子，如～～强强”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-椐"},{"id":"glyph-seal-691f","script":"seal","character":"椟","reading":"dú","description":"盛饭菜的食盒\n棺材\n椟 dú匣子；盒子买～还珠。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-椟"},{"id":"glyph-seal-6920","script":"seal","character":"椠","reading":"qiàn","description":"书的刻本\n椠本\n⒈〈古〉书写文字的板片。\n⒉书的板本旧～。宋～。\n⒊文简，书信。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-椠"},{"id":"glyph-seal-692d","script":"seal","character":"椭","reading":"tuǒ","description":"指某些长圆形的容器","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-椭"},{"id":"glyph-seal-693d","script":"seal","character":"椽","reading":"chuán","description":"chuán：(1)放在檩上架着屋顶的木条～子。～笔。\n(2)古代房屋间数的代称东宇西房数十～。”","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-椽"},{"id":"glyph-seal-6942","script":"seal","character":"楂","reading":"zhā；chá","description":"zhā：〔山～〕ａ．落叶乔木，果实球形，红色有白点，味酸，可食；ｂ．这种植物的果实。亦作山查”。\nchá：(1)同茬”。\n(2)水中木筏穷岸有盘～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-楂"},{"id":"glyph-seal-6954","script":"seal","character":"楔","reading":"xiē","description":"xiē：填充器物的空隙使其牢固的木橛、木片等～子。～形文字。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-楔"},{"id":"glyph-seal-695a","script":"seal","character":"楚","reading":"chǔ","description":"chǔ：(1)落叶灌木，鲜叶可入药。枝干坚劲，可以做杖。亦称牡荆”。\n(2)古代的刑杖，或学校扑责学生的小杖捶～。夏～。～掠（拷打）。～挞（拷打）。\n(3)中国春秋时国名～天（楚地的天空。因楚在南方，亦泛指南方天空）。～声。～歌（楚人之歌）。～狂。～腰（泛称女子的细腰）。～辞。四面～歌。～材晋用（指使用他国人才，或指人才外流）。\n(4)指中国湖北省和湖南省，特指湖北省～剧。\n(5)痛苦苦～。痛～。凄～。酸～。\n(6)清晰，鲜明，整洁清～。衣冠～～。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-楚"},{"id":"glyph-seal-695d","script":"seal","character":"楝","reading":"liàn","description":"liàn：落叶乔木，种子和树皮都可入药。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-楝"},{"id":"glyph-seal-6963","script":"seal","character":"楣","reading":"méi","description":"méi：(1)门框上的横木门～。\n(2)房屋的横梁，即二梁。\n(3)屋檐口，椽端的横板。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-楣"},{"id":"glyph-seal-6966","script":"seal","character":"楦","reading":"xuàn","description":"xuàn：(1)做鞋用的模型～子。鞋～。\n(2)拿东西把物体中空的部分填满使物体鼓起来鞋楦～鞋。装运鸡蛋，把箱子～好。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-楦"},{"id":"glyph-seal-696b","script":"seal","character":"楫","reading":"jí","description":"jí：(1)划船用具舟～。～师（船工）。中流击～。\n(2)古同辑”，聚集。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-楫"},{"id":"glyph-seal-696e","script":"seal","character":"楮","reading":"chǔ","description":"chǔ：(1)落叶乔木，树皮是制造桑皮纸和宣纸的原料。\n(2)纸的代称～币。～钱（旧俗祭祀时焚烧）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-楮"},{"id":"glyph-seal-696f","script":"seal","character":"楯","reading":"shǔn；dùn","description":"shǔn：栏杆的横木，也泛指栏杆。dùn：同“盾”，盾牌。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-6977","script":"seal","character":"楷","reading":"kǎi；jiē","description":"kǎi：(1)法式，模范～模。～范。～则。～式。\n(2)汉字的一种书体～书。正～。小～。～体。\njiē：落叶乔木，木材可制器具，种子可榨油，树皮和叶子可制栲胶。亦称黄连木”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-楷"},{"id":"glyph-seal-6978","script":"seal","character":"楸","reading":"qiū","description":"qiū：落叶乔木，干高叶大，木材质地致密，耐湿，可造船，亦可做器具～局。～枰（棋盘。古代多用楸木做成）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-楸"},{"id":"glyph-seal-6979","script":"seal","character":"楹","reading":"yíng","description":"yíng：(1)堂屋前部的柱子～联（亦称楹帖”）。\n(2)量词，古代计算房屋的单位，一说一列为一楹；一说一间为一楹。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-楹"},{"id":"glyph-seal-697c","script":"seal","character":"楼","reading":"lóu","description":"楼房的一层\n房间上部空间附设的可供藏物或住人的分层结构\n建筑在高处的建筑物\n⒈两层及两层以上的房屋～房。高～。又指楼房的一层我住二～。他住四～。\n⒉建筑物有上层结构的鼓～。城～。\n楼lǘ 1.见\"离楼\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-楼"},{"id":"glyph-seal-6982","script":"seal","character":"概","reading":"gài","description":"gài：(1)大略，总括大～。～论。～述。～貌。梗～。～要。～算。～括。～念（反映对象的本质属性的思维形式）。～率（概率论的基本概念。用来表示随机事件发生可能性大小的量称为此事件的概率”。亦称或然率”、几率”）。以偏～全。\n(2)情况，景象胜～（胜景，美丽的景色）。\n(3)一律一～而论。\n(4)气度，节操；气～。\n(5)刮平斗、斛用的小木板。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-概"},{"id":"glyph-seal-6986","script":"seal","character":"榆","reading":"yú","description":"yú：(1)落叶乔木，实扁圆，木材坚实，可制器具或供建筑用～荚。～钱儿（即榆荚”，像小铜钱）。～面（以榆皮磨制成粉，用为黏剂）。～塞（古称边塞植榆，故称边塞为榆塞”）。桑～暮景。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-榆"},{"id":"glyph-seal-6996","script":"seal","character":"榖","reading":"gǔ","description":"榖gǔ 1.落叶乔木。新生枝密披灰色粗毛，具乳汁。叶阔卵形至长圆状卵形，先端渐尖，全缘或缺裂。初夏开淡绿色小花，雌雄异株。果实圆球形，成熟时鲜红色。皮可制桑皮\n纸。又称构或楮。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-榖"},{"id":"glyph-seal-699b","script":"seal","character":"榛","reading":"zhēn","description":"zhēn：(1)落叶灌木或小乔木，结球形坚果，称榛子”，果仁可食。木材可做器物。\n(2)丛杂的草木～芜。莽～。～薄（草木丛生的地方，引申为指幽僻的地方）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-榛"},{"id":"glyph-seal-699c","script":"seal","character":"榜","reading":"bǎng；bàng","description":"bǎng：张贴出来的文告或名单～帖（官府的公告）§～。张～。光荣～。～文。发～。～眼（科举时代称殿试考取一甲第二名的人）。～书（原指写在宫阙门额上的大字，后泛指招牌一类的大型字）。\nbàng：摇船的用具～人（船工）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-榜"},{"id":"glyph-seal-69a7","script":"seal","character":"榧","reading":"fěi","description":"fěi：常绿乔木，种子有很硬的壳，两端尖，称榧子”，仁可食，亦可入药、榨油。木质坚硬，可做建筑材料。通称香榧”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-榧"},{"id":"glyph-seal-69ad","script":"seal","character":"榭","reading":"xiè","description":"xiè：(1)建筑在台上的房屋水～。歌台舞～。\n(2)古代的讲武堂。\n(3)古代指藏乐器的地方。\n(4)古代指没有房间的庙堂。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-榭"},{"id":"glyph-seal-69b1","script":"seal","character":"榱","reading":"cuī","description":"cuī：椽子栋折～崩。”","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-榱"},{"id":"glyph-seal-69b7","script":"seal","character":"榷","reading":"què","description":"què：(1)渡水的横木。\n(2)专卖～货。～场（征收专卖税的交易场所）。～税（专卖业的税）。\n(3)商讨商～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-榷"},{"id":"glyph-seal-69bb","script":"seal","character":"榻","reading":"tà","description":"tà：狭长而较矮的床，亦泛指床竹～。藤～。卧～。下～（客人住宿）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-榻"},{"id":"glyph-seal-69c1","script":"seal","character":"槁","reading":"gǎo","description":"gǎo：(1)枯干～木。枯～。～悴。～木死灰（喻心情冷漠，对一切事情无动于衷）。\n(2)古同藁”，草。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-槁"},{"id":"glyph-seal-69ca","script":"seal","character":"槊","reading":"shuò","description":"shuò：长矛，古代的一种兵器横～赋诗”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-槊"},{"id":"glyph-seal-69cc","script":"seal","character":"槌","reading":"chuí","description":"chuí：(1)敲打用具～儿。棒～。鼓～子。\n(2)古同捶”，敲打。\n(3)古代架蚕箔的木柱。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-槌"},{"id":"glyph-seal-69ce","script":"seal","character":"槎","reading":"chá","description":"chá：(1)木筏浮～。泛～。星～。乘～。\n(2)同茬”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-槎"},{"id":"glyph-seal-69d0","script":"seal","character":"槐","reading":"huái","description":"huái：(1)落叶乔木。木材可供建筑和制家具。花蕾可做黄色染料～火（用槐木取火）。～序。～楝（ａ．中国周代朝廷种三槐九棘，公卿大夫分坐其下，后因以槐棘”指三公或三公之位；ｂ．指听讼的处所。均亦称棘槐”）。～鼎（喻三公）。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-槐"},{"id":"glyph-seal-69d4","script":"seal","character":"槔","reading":"gāo","description":"槔（檙）gāo","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-槔"},{"id":"glyph-seal-69db","script":"seal","character":"槛","reading":"kǎn；jian","description":"槛车;囚车\n⒉栏杆，栏板。\n⒊见kǎn。\n⒉见jiàn。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-槛"},{"id":"glyph-seal-69ed","script":"seal","character":"槭","reading":"qì；sè","description":"qì：落叶小乔木，树干平滑，叶对生，掌状分裂，秋季变为红色或黄色。花黄绿色，结翅果，能借风力散布种子。木材可做器具。\nsè：树枝光秃的样子，树叶凋落庭树～以洒落兮”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-槭"},{"id":"glyph-seal-69fd","script":"seal","character":"槽","reading":"cáo","description":"cáo：(1)一种长方形或正方形的较大的盛东西的器具～子。水～。酒～。～坊。\n(2)特指用来盛饲料喂牲畜的器具马～。猪食～。～头。\n(3)槽状的～钢。～铁。～牙。\n(4)两边高起，中间凹下物体的凹下部分河～。在石头上凿个～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-槽"},{"id":"glyph-seal-6a0a","script":"seal","character":"樊","reading":"fán","description":"fán：(1)笼子～笼（关鸟兽的笼子，喻不自由的境地）。\n(2)篱笆～篱（喻对事物的限制）。\n(3)纷杂的样子～然淆乱”。\n(4)姓","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-樊"},{"id":"glyph-seal-6a17","script":"seal","character":"樗","reading":"chū","description":"chū：〔～树〕即臭椿”。\n〔～蚕〕一种蚕，幼虫绿色，有白色黏粉，成虫灰白色，幼虫吃樗叶、蓖麻叶等。亦称椿蚕”。\n〔～蒲〕古代一种赌博游戏，像后代的掷骰子，后亦作为赌博的通称。\n〔～栎〕喻无用之材，亦作自谦之辞。亦称樗材”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-樗"},{"id":"glyph-seal-6a18","script":"seal","character":"樘","reading":"táng","description":"táng：(1)门框或窗框门～。窗～。\n(2)量词，指一套门（窗）框或门（窗）扇一～玻璃门。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-樘"},{"id":"glyph-seal-6a21","script":"seal","character":"模","reading":"mó；mú","description":"mó：(1)法式，规范，标准～范。～式。楷～。～型。～本。～压。\n(2)仿效～仿（亦作摹仿”）。～拟（亦作摹拟”）。～写。\n(3)特指模范”劳～。英～。\nmú：用压制或浇注的方法使材料成为一定形状的工具～子。～板。～具。\n〔～样〕ａ．人的长相或装束打扮的样子；ｂ．表示约略的时间、怎么办；ｃ．描摹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-模"},{"id":"glyph-seal-6a2a","script":"seal","character":"横","reading":"héng；hèng","description":"héng：(1)跟地面平行的，与竖”、直”相对～梁。～楣。～额。～幅。～批。～披（长条形横幅字画）。～匾。～标。～空。\n(2)左右向的，跟目视方向垂直的，与竖”、直”、纵”相对～写。～排。～向。～斜。纵～。\n(3)地理学上指东西向的与纵”相对～贯东西。\n纵；直；竖；\nhèng：(1)凶暴，不讲理；蛮～。强～。～暴。～蛮。\n(2)意外的，不寻常的～财。～祸。～事。～死。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-横"},{"id":"glyph-seal-6a31","script":"seal","character":"樱","reading":"yīng","description":"樱桃花\n樱花\n樱桃","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-樱"},{"id":"glyph-seal-6a35","script":"seal","character":"樵","reading":"qiáo","description":"qiáo：(1)柴，散木～苏（柴草，亦指打柴割草）。采～。\n(2)打柴～夫。～客。\n(3)古同谯”，谯楼。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-樵"},{"id":"glyph-seal-6a3d","script":"seal","character":"樽","reading":"zūn","description":"zūn：古代盛酒的器具春风东来忽相过，金～渌酒生微波”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-樽"},{"id":"glyph-seal-6a50","script":"seal","character":"橐","reading":"tuó","description":"tuó：(1)口袋负书担～。\n(2)古代的一种鼓风吹火器具炉～，～以牛皮”。\n〔～驼〕即骆驼”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-橐"},{"id":"glyph-seal-6a58","script":"seal","character":"橘","reading":"jú；jv","description":"jú：常绿乔木，果实称橘子”，多汁，味酸甜可食。种子、树叶、果皮均可入药～红。～络。～黄色。～化为枳（喻人必然受环境的影响而发生变化）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-橘"},{"id":"glyph-seal-6a59","script":"seal","character":"橙","reading":"chéng","description":"chéng：(1)常绿乔木或灌木，果实称橙子”，多汁，品种很多，可食。皮可入药～皮。～汁。甜～。\n(2)红和黄合成的颜色～黄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-橙"},{"id":"glyph-seal-6a5b","script":"seal","character":"橛","reading":"jué","description":"jué：(1)小木桩～子。\n(2)树或庄稼的残茎残～。树～。\n(3)木制的马嚼子。\n(4)一小段伏惟烂木一～。佛与众生不别”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-橛"},{"id":"glyph-seal-6a79","script":"seal","character":"橹","reading":"lǔ","description":"顶部没有覆盖的远望楼\n比桨长大的划船工具,安在船尾或船旁\n⒊艪、\n⒈大盾牌。\n⒉望楼，瞭望台泰山为～。\n⒊船桨，拨水使船前进的工具摇～。大舶夹双～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-橹"},{"id":"glyph-seal-6a80","script":"seal","character":"檀","reading":"tán","description":"tán：(1)落叶乔木，木质坚硬，用于制家具、乐器（亦称青檀”）。\n(2)浅绛色～口（形容红艳的嘴唇）。\n(3)姓。\n〔～香〕常绿乔木，产在热带及亚热带，木质坚硬，有香气，可制器物及香料，又可入药。\n〔紫～〕常绿乔木，木材坚硬，带红色，可制贵重家具或工艺品。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-檀"},{"id":"glyph-seal-6a84","script":"seal","character":"檄","reading":"xí","description":"xí：古代官府用以征召或声讨的文书此臣之所谓传～而千里定者也”。～文。羽～。～移（文体名，檄文”与移文”的合称。檄文多用于声讨和征伐；移文多用于晓喻或责备）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-檄"},{"id":"glyph-seal-6a90","script":"seal","character":"檐","reading":"yán","description":"yán：(1)房顶伸出墙壁的部分房～儿。廊～。飞～。前～。～沟。～头。～牙。\n(2)覆盖物的边沿或伸出的部分帽～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-檐"},{"id":"glyph-seal-6a97","script":"seal","character":"檗","reading":"bò","description":"bò：〔黄～〕落叶乔木，木材坚硬，茎可制黄色染料，树皮入药。简称檗”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-檗"},{"id":"glyph-seal-6aa0","script":"seal","character":"檠","reading":"qíng","description":"qíng：(1)灯架，烛台灯～。\n(2)借指灯孤～。\n(3)矫正弓弩的器具。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-檠"},{"id":"glyph-seal-6b20","script":"seal","character":"欠","reading":"qiàn","description":"qiàn：(1)人在疲倦时张口出气打哈～。\n(2)身体稍稍向上移动～身。\n(3)短少，不够～缺。～安。\n(4)借别人的财物没有还或应当给人的事物还没有给拖～。～账。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-欠"},{"id":"glyph-seal-6b21","script":"seal","character":"次","reading":"cì","description":"cì：(1)第二～日。～子。～等。～要。\n(2)质量、品质较差的～品。～货。\n(3)等第，顺序～第。～序。名～。\n(4)化学上指酸根或化合物中少含两个氧原子的～氯酸。\n(5)中间胸～。\n(6)量词，回～数（shù）。初～。三番五～。\n(7)旅行所居止之处所旅～。舟～。～所。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-次"},{"id":"glyph-seal-6b22","script":"seal","character":"欢","reading":"huān","description":"⒈喜悦，高兴～喜。～庆。～度。～笑。～迎。～欣。～腾。～呼。\n⒉活跃，起劲小孩子们可～。他干得真～。这部机器转得很～。〈引〉旺盛炉火正～。\n欢huàn 1.祸害;灾难。\n欢guàn 1.忧惧无处诉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-欢"},{"id":"glyph-seal-6b23","script":"seal","character":"欣","reading":"xīn","description":"xīn：快乐，喜欢～～（ａ．高兴的样子，如～～而来”；ｂ．草木生机旺盛的样子，如～～向荣”，亦泛指蓬勃发展）。～喜。欢～鼓舞。～然。～赏。～幸。～慕。～悦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-欣"},{"id":"glyph-seal-6b24","script":"seal","character":"欤","reading":"yú","description":"表疑问语气\n表感叹语气\n表反诘语气","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-欤"},{"id":"glyph-seal-6b27","script":"seal","character":"欧","reading":"ōu","description":"通讴”。歌唱\n同驱”\n驱使;疾行\n通殴”。殴打\n通区”\n通瓯”。种族名\n欧罗巴洲的简称\n欧姆的简称\n欧ǒu 1.\"呕\"的古字。呕吐。 2.指呕吐声。 3.通\"殴\"。捶击。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-欧"},{"id":"glyph-seal-6b32","script":"seal","character":"欲","reading":"yù","description":"yù：(1)想得到某种东西或想达到某种目的的要求～念。～望。～火。食～。情～。禁～。纵～。\n(2)想要，希望～盖弥彰。～罢不能。～速不达。\n(3)需要胆～大而心～细。\n(4)能要摇摇～坠。山雨～来风满楼。\n(5)婉顺的样子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-欲"},{"id":"glyph-seal-6b38","script":"seal","character":"欸","reading":"ǎi；ēi；éi；ěi；èi","description":"ǎi：用于“欸乃”，形容摇橹等声音。其余读音多用作叹词，表示招呼、疑问或应答。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-6b3a","script":"seal","character":"欺","reading":"qī","description":"qī：(1)诈骗，蒙混～骗。～诈。～哄。～瞒。～诬。～诳。～蒙。童叟无～。\n(2)压迫，侮辱～负。～侮。～压。～凌。～生。～善怕恶。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-欺"},{"id":"glyph-seal-6b3e","script":"seal","character":"款","reading":"kuǎn","description":"kuǎn：(1)诚恳～留。～曲（qǔ）（殷勤的心意）。～待。～洽（亲切融洽）。～诚。～语（恳切谈话）。\n(2)器物上刻的字，书画、信件头尾上的名字落～（题写名字）。题～。\n(3)式样～式。\n(4)法规条文里分的项目条～。第三条第一～。\n(5)经费，钱财～项。～额。公～。存～。汇～。\n(6)敲打，叩～门。～打。～塞。～关而入。\n(7)至绕黄山而～牛首”。\n(8)留，招待～客。\n(9)空～言不听，奸乃不生”。\n(10)缓慢～步。～～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-款"},{"id":"glyph-seal-6b43","script":"seal","character":"歃","reading":"shà","description":"shà：用嘴吸取。\n〔～血〕古人盟会时，嘴唇涂上牲畜的血，表示诚意，如～～为盟”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-歃"},{"id":"glyph-seal-6b46","script":"seal","character":"歆","reading":"xīn","description":"xīn：(1)喜爱，羡慕～羡。～慕。\n(2)飨，祭祀时神灵享受祭品、香火～享。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-歆"},{"id":"glyph-seal-6b47","script":"seal","character":"歇","reading":"xiē","description":"xiē：(1)休息～憩。～脚。～晌。安～。～凉。～心。\n(2)停止～止。～业。～工。停～。间～。～班。～后语。\n(3)很短的一段时间过了一～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-歇"},{"id":"glyph-seal-6b49","script":"seal","character":"歉","reading":"qiàn","description":"qiàn：(1)觉得对不住人～意。～疚。抱～。道～。\n(2)收成不好～年。～岁。～收。以丰补～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-歉"},{"id":"glyph-seal-6b4c","script":"seal","character":"歌","reading":"gē","description":"gē：(1)唱～唱。～咏。～颂。～坛。～台舞榭。～舞。能～善舞。\n(2)能唱的文词唱～。～谱。～词。～诀。民～。诗～。～行（xíng）（旧诗的一种体裁，音节、格律比较自由）。诗言志，～咏言。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-歌"},{"id":"glyph-seal-6b59","script":"seal","character":"歙","reading":"xī；shè","description":"xī：(1)收敛，吸进将欲～之，必固张之”。\n(2)古同翕”，和洽。\nshè：〔～县〕地名，在中国安徽省。简称歙”，如～砚”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-歙"},{"id":"glyph-seal-6b62","script":"seal","character":"止","reading":"zhǐ","description":"zhǐ：(1)停住不动～步。截～。\n(2)拦阻，使停住～痛。禁～。\n(3)仅，只～有此数。不～一回。\n(4)古同趾”，脚；脚趾头。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-止"},{"id":"glyph-seal-6b63","script":"seal","character":"正","reading":"zhèng；zhēng","description":"zhèng：不偏斜，符合标准；端正，改正；正在。zhēng：用于正月。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-6b64","script":"seal","character":"此","reading":"cǐ","description":"cǐ：(1)这，这个，与彼”相对～间。～后。～生。长～以往（老是这样下去）。从～。因～。\n(2)这里，这儿到～为止。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-此"},{"id":"glyph-seal-6b65","script":"seal","character":"步","reading":"bù","description":"bù：(1)行走～兵。～行（xíng）。徒～。信～。闲～。固～自封。望而却～。\n(2)踏着别人的足迹走，追随～韵。～其后尘。～武前贤。\n(3)行走时两脚的距离～伐。～测。寸～难行。\n(4)事情进行的程序、阶段、程度～骤。初～。\n(5)中国旧制长度单位，一步等于五尺。\n(6)古同埠”，多用于地名。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-步"},{"id":"glyph-seal-6b66","script":"seal","character":"武","reading":"wǔ","description":"wǔ：(1)关于军事或技击的，与文”相对～装。～器。～警。～林。～坛。～生。～旦。～丑。～净。～举。\n(2)勇猛，猛烈英～。威～。～断。～士。～夫。\n(3)半步，泛指脚步步～。踵～。行（xíng）不数～。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-武"},{"id":"glyph-seal-6b79","script":"seal","character":"歹","reading":"dǎi","description":"dǎi：不好、坏、恶～人。～意。～毒（阴险狠毒）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-歹"},{"id":"glyph-seal-6b7b","script":"seal","character":"死","reading":"sǐ","description":"sǐ：(1)丧失生命，与生”、活”相对～亡。～讯。～刑。～囚。～棋。～地。生离～别。～有余辜。\n(2)不顾生命～志（牺牲生命的决心）。～士（敢死的武士）。～战。\n(3)固执，坚持到底～心塌地。～卖力气。\n(4)无知觉睡得～。\n(5)不活动，不灵活～结。～理。～板。\n(6)不通达～胡同。～路一条。\n(7)过时，失去作用～文字。\n(8)极，甚乐～人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-死"},{"id":"glyph-seal-6b7c","script":"seal","character":"歼","reading":"jiān","description":"消灭，全部消除，如歼灭。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-6b82","script":"seal","character":"殂","reading":"cú","description":"cú：死亡～落。～谢。～陨。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殂"},{"id":"glyph-seal-6b83","script":"seal","character":"殃","reading":"yāng","description":"yāng：(1)祸害灾～。遭～。城门失火，～及池鱼（喻牵连受害）。\n(2)损害祸国～民。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殃"},{"id":"glyph-seal-6b84","script":"seal","character":"殄","reading":"tiǎn","description":"tiǎn：尽，绝～灭。～歼。暴～天物（任意糟蹋东西）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殄"},{"id":"glyph-seal-6b86","script":"seal","character":"殆","reading":"dài","description":"dài：(1)危危～。熙～哉。知足不辱，知止不～（懂得满足不贪心就不会受辱，懂得适可而止就不会遭到危险）。\n(2)大概，几乎伤亡～尽。\n(3)古同怠”，懈怠。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殆"},{"id":"glyph-seal-6b87","script":"seal","character":"殇","reading":"shāng","description":"横死,非正常死亡\n未成年而死的人。亦称殇子”\n病变而药不变,向之寿民,今","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殇"},{"id":"glyph-seal-6b8a","script":"seal","character":"殊","reading":"shū","description":"shū：(1)不同～途同归。悬～。\n(2)特别，很～功。～荣。～勋。特～。\n(3)断，绝～死。\n(4)超过母氏年～七十”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殊"},{"id":"glyph-seal-6b8b","script":"seal","character":"残","reading":"cán","description":"①不完整～缺。\n②剩余的；快完了的～冬。\n③伤害；毁坏～害。\n④凶恶～忍、～酷。\n【残杯冷炙】见【残羹冷炙】。\n【残编断简】残缺不全的书籍。又作残篇断简、断编残简、断简残篇、断简残编。\n【残羹】吃剩的酒食。残羹剩饭剩菜。冷炙已凉的烤肉。又作残杯冷炙。\n【残骸】人或动物不完整的尸骨。借指残破的建筑物、机械、车辆等。\n【残年】\n①指人的晚年风烛～。\n②一年将尽的时候。\n【残篇断简】见【残编断简】。\n【残渣余孽】比喻残存的坏人，未消灭干净的邪恶势力。\n【残障】残疾。\n【残照】落日的光。蚕家蚕、柞蚕等的统称。蚕丝是纺织绸缎的重要原料。\n【蚕豆】豆科。一年生或越年生草本植物。茎方中空，花白色有紫斑。种子供食用，茎杆作饲料或肥料『代从西域传入，我国主要分布在西南、华中和华东。又叫胡豆。\n【蚕食】像蚕吃桑叶一样。比喻一步步地侵占。惭羞愧大言不～。\n【惭色】羞愧的表情。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-残"},{"id":"glyph-seal-6b96","script":"seal","character":"殖","reading":"zhí；shi","description":"zhí：(1)孳生生～。养～。繁～。～民地。\n(2)种植农～嘉谷”。\n(3)兴生财利货～（经商）。\nshi：〔骨～〕尸骨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殖"},{"id":"glyph-seal-6b9a","script":"seal","character":"殚","reading":"dān","description":"殚 dān,用尽；竭尽～力、～心。\n【殚精竭虑】用尽心思谋虑。瘅 dān又见dàn。\n【瘅疟】一种疟疾。主要症状是发高烧，烦躁，口渴，呕吐等。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殚"},{"id":"glyph-seal-6b9b","script":"seal","character":"殛","reading":"jí","description":"jí：杀死雷～（突遭雷击致死）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殛"},{"id":"glyph-seal-6ba1","script":"seal","character":"殡","reading":"bìn","description":"泛指丧葬事务\n殡 bìn停放灵柩；把灵柩送出埋葬或火化～葬、送～。\n【殡车】出殡时运送灵枢的车。\n【殡葬】出殡和埋葬。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殡"},{"id":"glyph-seal-6baa","script":"seal","character":"殪","reading":"yì","description":"yì：(1)死左骖～兮右刃伤”。\n(2)杀死～此大兕”。\n(3)跌倒奔～百余里间”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殪"},{"id":"glyph-seal-6bb4","script":"seal","character":"殴","reading":"ōu","description":"同怄”。气恼\n假借为驱”。驱赶\n殴kōu 1.见\"殴蛇\"。\n殴qū 1.驱赶;驱使。\n殴ǒu 1.呕，呕吐。参见\"殴血\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殴"},{"id":"glyph-seal-6bb5","script":"seal","character":"段","reading":"duàn","description":"duàn：(1)事物、时间的一节阶～。地～。片～。～落。\n(2)工矿企业中的行政单位工～。机务～。\n(3)围棋棋手等级的名称～位。\n(4)古同缎”，绸缎。\n(5)古同锻”，锻炼。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-段"},{"id":"glyph-seal-6bb7","script":"seal","character":"殷","reading":"yīn；yān；yǐn","description":"yīn：(1)富裕，富足～实。～阜。～富。\n(2)深厚，恳切情意甚～。～切。～勤。\n(3)众，多士与女，～其盈矣”。\n(4)盛，大～祭。\n(5)中国朝代名，商代的后期，由盘庚起称殷”～墟。\n(6)姓。\nyān：黑红色～红。\nyǐn：(1)雷声～其雷，在南山之阳”。\n(2)震动熊咆龙吟～岩泉”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殷"},{"id":"glyph-seal-6bbf","script":"seal","character":"殿","reading":"diàn","description":"diàn：(1)高大的房屋，特指帝王所居和朝会的地方，或供奉神佛的地方宫～。宝～。金銮～。～堂。～阁。～上虎（喻敢谏之臣）。～试。\n(2)在最后～后。～军。\n〔～下〕对亲王或太子的敬称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-殿"},{"id":"glyph-seal-6bc1","script":"seal","character":"毁","reading":"huǐ","description":"huǐ：(1)破坏损害～灭。～害。～弃。销～。\n(2)烧掉烧～。焚～。\n(3)把成件的旧东西改造成别的东西一张旧桌子～成两个小凳子。\n(4)诽谤，说别人的坏话～谤。～誉。诋～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毁"},{"id":"glyph-seal-6bc2","script":"seal","character":"毂","reading":"gū","description":"泛指车","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毂"},{"id":"glyph-seal-6bc5","script":"seal","character":"毅","reading":"yì","description":"yì：果决，志向坚定而不动摇沉～。刚～。坚～。～力（坚强持久的意志）。～然。～勇。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毅"},{"id":"glyph-seal-6bcb","script":"seal","character":"毋","reading":"wú","description":"wú：(1)不要，不可以～妄言。宁缺～滥。\n(2)不～庸。～宁（nìng）。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毋"},{"id":"glyph-seal-6bcd","script":"seal","character":"母","reading":"mǔ","description":"mǔ：(1)妈妈，娘～亲。～性。～系。慈～。～忧（称母亲去世）。\n(2)对女性长辈的称呼姑～。舅～。\n(3)雌性的，与公”相对～鸡。\n(4)事物据以产生出来的～国。～校。～音（元音）。\n(5)一套东西中间可以包含其他部分的螺丝～。子～扣。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-母"},{"id":"glyph-seal-6bcf","script":"seal","character":"每","reading":"měi","description":"měi：(1)指特定范围内的任何一个或一组～人。～回。～组。\n(2)指特定范围内逐一出现的任何一次～战必胜。～况愈下。\n(3)虽～有良朋，况也永叹”（虽有良朋好友，危难之时也只能为之长叹）。\n(4)古同们”，中国宋元代口语。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-每"},{"id":"glyph-seal-6bd2","script":"seal","character":"毒","reading":"dú；dài","description":"dú：(1)有害的性质或有害的东西～气。～性。～饵。～药。～蛇。吸～。贩～。\n(2)害，伤害～害。～化。～杀。莫予～也（没有谁能桅我，即谁也不能把我怎么样）。\n(3)凶狠，猛烈～辣。～计。～刑≥～。恶～。\n(4)恨，以为苦令人愤～。\ndài：古同玳”，玳瑁。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毒"},{"id":"glyph-seal-6bd3","script":"seal","character":"毓","reading":"yù","description":"yù：(1)同育”，多用于人名。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毓"},{"id":"glyph-seal-6bd4","script":"seal","character":"比","reading":"bǐ","description":"bǐ：(1)较量高低、长短、远近、好坏等～赛。～附。对～。评～。\n(2)能够相匹今非昔～。无与伦～。\n(3)表示比赛双方胜负的对比三～二。\n(4)表示两个数字之间的倍数、分数等关系～例。～值。\n(5)譬喻，摹拟～如。～方。～兴（xìng）（文学写作的两种手法。比”是譬喻；兴”是烘托）。～画。～况（比照，相比）。\n(6)靠近，挨着～～（一个挨一个，如～～皆是”）。～肩继踵。～邻。鳞次栉～。\n(7)和，亲～顺。\n(8)及，等到～及。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-比"},{"id":"glyph-seal-6bd5","script":"seal","character":"毕","reading":"bì","description":"毕宿。星名。二十八宿之一,西方白虎七宿的第五宿,有星八颗。以其形状像毕网得名\n用毕猎取\n①终结；完成～业、礼～。\n②全、完全原形～露。\n③二十八宿之一。\n④姓。\n【毕达哥拉斯定理】见【勾股定理】。\n【毕恭毕敬】见【必恭必敬】。\n【毕生】一生；终生～的精力。\n【毕业论文】高等学校学生学习期满，独立撰写的带有研究性质的文章。一般要求毕业论文成绩及格，方能毕业。\n【毕业设计】高等学校各种技术科学专业学生学习期满，综合运用有关课程的理论和技术作出解决实际问题的设计。一般要求毕业设计成绩及格，方能毕业。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毕"},{"id":"glyph-seal-6bd6","script":"seal","character":"毖","reading":"bì","description":"bì：(1)谨慎惩前～后（接受过去失败的教训，以后小心不重犯）。\n(2)操劳无～于恤”。\n(3)古同泌”，泉水冒出流淌的样子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毖"},{"id":"glyph-seal-6bd9","script":"seal","character":"毙","reading":"bì","description":"垮台,失败\n引申为死\n③枪毙。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毙"},{"id":"glyph-seal-6bdb","script":"seal","character":"毛","reading":"máo","description":"máo：(1)动植物的皮上所生的丝状物～笔。羽～。～织品。～骨悚然。轻于鸿～。\n(2)像毛的东西，指谷物或草不～之地。\n(3)衣物上的霉菌老没见太阳都长～了。\n(4)粗糙，没有加工的～布。～估（粗略地估计）。～坯。\n(5)不是纯净的～利。～重。\n(6)行动急躁～躁。\n(7)惊慌失措，主意乱了把他吓～了。\n(8)小～病。～孩子。～～雨。\n(9)货币贬值钱～了。\n(10)量词，用于钱币，等于角”，一圆钱的十分之一两～钱。\n(11)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毛"},{"id":"glyph-seal-6be1","script":"seal","character":"毡","reading":"zhān","description":"毡包\n这个时候,一个牧民匆匆忙忙钻进毡包来\n他背着毡包到野外去接回初生的羊羔\n⒈用兽毛压制而成的片状物，可作各种垫衬材料或防寒用品等～帽。～子毯。\n⒉像毡的东西油毛～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毡"},{"id":"glyph-seal-6beb","script":"seal","character":"毫","reading":"háo","description":"háo：(1)细长而尖的毛～毛。～发（fà）。～末（喻极微小的数量或部分）。丝～。\n(2)指毛笔挥～。～素。\n(3)中国的秤或戥子上的提绳头～。二～。\n(4)中国市制计量单位，十毫等于一厘（长度、地积、重量单位）；一百平方毫等于一平方厘（面积单位）。\n(5)方言，货币单位，角、毛。\n(6)数量极少，一点儿（限用于否定式）～不费力。～无二致。\n(7)与某一物理量的单位连用时，表示该量的千分之一～米（公制长度单位，米”的千分之一。）","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毫"},{"id":"glyph-seal-6bf3","script":"seal","character":"毳","reading":"cuì","description":"cuì：鸟兽的细毛。\n〔～毛〕医学上指人体表面除头发、阴毛、腋毛外，其他部位生的细毛。俗称寒毛”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毳"},{"id":"glyph-seal-6bf9","script":"seal","character":"毹","reading":"shū","description":"shū：〔氍～〕见氍”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-毹"},{"id":"glyph-seal-6c05","script":"seal","character":"氅","reading":"chǎng","description":"chǎng：(1)大衣，外套大～。\n(2)古代指一种像鹤的水鸟的羽毛，用以做衣服和仪仗中的旗幡鹤～。戈～。戟～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-氅"},{"id":"glyph-seal-6c0d","script":"seal","character":"氍","reading":"qú","description":"qú：〔～毹〕毛织的地毯，旧时演戏多用来铺在地上或台上，因此常用氍毹”或红氍毹”代称舞台。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-氍"},{"id":"glyph-seal-6c0f","script":"seal","character":"氏","reading":"shì；zhī","description":"shì：(1)古代姓”和氏”分用。姓是总的，氏是分支，后来姓和氏不分，可以混用。\n(2)古代称呼帝王贵族等，后称呼名人、专家神农～。太史～。摄～表。\nzhī：〔阏（yān）～〕见阏”。\n〔月～〕见月”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-氏"},{"id":"glyph-seal-6c10","script":"seal","character":"氐","reading":"dī；dǐ","description":"dī：(1)中国古代民族，居住在今西北一带，东晋时建立过前秦、后凉。\n(2)星名，二十八宿之一。\ndǐ：根本。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-氐"},{"id":"glyph-seal-6c11","script":"seal","character":"民","reading":"mín","description":"mín：(1)以劳动群众为主体的社会基本成员人～。～主。～国。～法。公～（在一国内有国籍，享受法律上规定的公民权利并履行公民义务的人）。国～（具有国籍的人）。\n(2)指人或人群居～。～族。\n(3)劳动大众的，非官方的～间。～歌。～谚。～风。～情。\n(4)某族的人汉～。回～。\n(5)从事不同职业的人农～。渔～。\n(6)非军事的～品。～航。\n(7)同苠”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-民"},{"id":"glyph-seal-6c13","script":"seal","character":"氓","reading":"máng；méng","description":"méng：古代称民（特指外来的）～隶（充当隶役的平民）。群～。\nmáng：〔流～〕见流”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-氓"},{"id":"glyph-seal-6c14","script":"seal","character":"气","reading":"qì","description":"此天子气也。\n气体的通称\n⒈无一定形状，能自由散布的物体～体。煤～。水蒸～。特指空气～压。吸～。\n⒉呼吸～息。～喘。屏～。上～不接下～。\n⒋闻到的味儿～味。香～。烟～。\n⒌人的精神状态、作风、风度、力量等朝～。骄～。怒～。娇～。勇～。～宇。～节。～魄。\n⒍怒，使人发怒生～。不要～我嘛！\n⒎欺负，欺压受～。\n⒏气势，气氛～壮山河。喜～洋洋。\n⒐中医指体内具有某种功能的物质～虚。～血两亏。也指某种症象湿～。痰～。\n⒑迷信者所谓的\"命运\"～数、运～等都是无稽之谈。\n①云气。\n②某种环境中反映出来的状态情景和谐的～氛。\n气xì 1.馈赠粮饷。 2.指食物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-气"},{"id":"glyph-seal-6c1b","script":"seal","character":"氛","reading":"fēn","description":"fēn：气，气象，情势气～。～围（周围的气氛和情调）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-氛"},{"id":"glyph-seal-6c34","script":"seal","character":"水","reading":"shuǐ","description":"自然界中的水，也常用来指河流。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-seal-6c38","script":"seal","character":"永","reading":"yǒng","description":"yǒng：(1)水流长江之～矣”。\n(2)久远～远。～生。隽～。～昼（长昼）。～年（ａ．整年；ｂ．长寿）。～诀。～志不忘。～垂不朽。\n(3)古同咏”，以诗词等来叙述。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-永"},{"id":"glyph-seal-6c40","script":"seal","character":"汀","reading":"tīng","description":"tīng：水边平地，小洲～洲。绿～。～线（海岸被海水侵蚀而成的线状痕迹）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汀"},{"id":"glyph-seal-6c41","script":"seal","character":"汁","reading":"zhī","description":"zhī：混有某种物质的水～液。墨～。果～。胆～。脑～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汁"},{"id":"glyph-seal-6c42","script":"seal","character":"求","reading":"qiú","description":"qiú：(1)设法得到～生。～成。～知。～索。～证（寻求证据，求得证实）。～实（讲求实际）。～同存异。～全责备。～贤若渴。实事～是。\n(2)恳请，乞助～人。～告。～乞。～医。～教。～助。\n(3)需要需～。供过于～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-求"},{"id":"glyph-seal-6c47","script":"seal","character":"汇","reading":"huì","description":"用外币或本国货币兑换的票据\n收集、分类和分送各种信息或其它需要广泛分送的情况或项目\n能汇\n中子汇\n河流会合\n迂回,围绕\n以即期汇票、\n⒈水流会合～成江河。\n⒉从甲地寄款到乙地～款。～兑。电～。\n⒊外汇多出口，多创～。\n⒋综合，聚合。会聚在一起～集。～编。词～。总～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汇"},{"id":"glyph-seal-6c49","script":"seal","character":"汉","reading":"hàn","description":"汉水，长江支流；汉朝的简称；汉族及汉语的简称；成年男子，如好汉。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-6c55","script":"seal","character":"汕","reading":"shàn","description":"shàn：古代称抄网类的捕鱼用具。\n〔～～〕群鱼游水的样子，如南有嘉鱼，丞然～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汕"},{"id":"glyph-seal-6c57","script":"seal","character":"汗","reading":"hàn；hán","description":"hàn：(1)由身体的毛孔排泄出来的液体～水。～流浃背。\n(2)出汗，使出汗～颜（因羞惭而出汗；泛指惭愧）。～马功劳。～牛充栋。\nhán：〔可（kè）～〕见可2”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汗"},{"id":"glyph-seal-6c5b","script":"seal","character":"汛","reading":"xùn","description":"xùn：(1)江河定期的涨水～期。～情。防～。桃花～（桃花盛开时发生的河水暴涨。亦称桃汛”）。\n(2)洒～扫（ａ．洒扫；ｂ．扫除，清除）。\n(3)古同讯”～地（中国清代兵制，凡千总、把总、外委所统率的绿营兵均称汛”，其驻防巡逻的地区称汛地”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汛"},{"id":"glyph-seal-6c5c","script":"seal","character":"汜","reading":"sì","description":"sì：(1)水决后又流入。\n(2)不流通的小沟渠。\n〔～水〕水名，在中国河南省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汜"},{"id":"glyph-seal-6c5d","script":"seal","character":"汝","reading":"rǔ","description":"rǔ：(1)你～辈。～等。～曹。～将何经。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汝"},{"id":"glyph-seal-6c5f","script":"seal","character":"江","reading":"jiāng","description":"较大的河流。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-seal-6c60","script":"seal","character":"池","reading":"chí","description":"chí：(1)水塘，多指人工挖的～子。水～。～鱼之殃（喻因牵连而受到的灾祸。亦称池鱼之祸”）。\n(2)湖～盐（从咸水湖采取的盐，成分和海盐相同）。\n(3)像水池的浴～。花～。乐（yuè）～。舞～。\n(4)护城河城～。金城汤～。\n(5)旧时指剧场中正厅前部～座。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-池"},{"id":"glyph-seal-6c61","script":"seal","character":"污","reading":"wū","description":"wū：(1)浑浊的水粪～。血～。\n(2)肮脏，不干净～水。～泥。～浊。\n(3)肮脏的东西～渍。～垢。\n(4)不廉洁贪～。\n(5)弄脏玷～。～损。～辱。～蔑（ａ．玷污；ｂ．诬蔑）。～染。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-污"},{"id":"glyph-seal-6c64","script":"seal","character":"汤","reading":"tāng","description":"⒈热水，开水赴～蹈火。\n⒉烹调时加水汁多的副食蛋花～。什锦～。\n⒊煮食品的汁液米～。菜～。肉～。\n⒋中药汤剂～药。柴胡～。四物～。\n汤tàng 1.高温物体与皮肤接触而使之产生疼痛感。 2.把肉﹑菜放进开水里稍微煮一下就取出来。 3.泛指煮。 4.用开水或热水浇﹑泡。 5.用热物接触冷物使之变暖。\n6.冲撞;冒。 7.搪，抵挡。 8.触，碰。 9.用同\"淌\"。 10.用同\"趟\"。参见\"汤汤儿\"。 11.通\"荡\"。行为放纵。 12.通\"荡\"。大。参见\"汤禹\"。 13.通\"荡\"。荡涤\n汤shāng 1.见\"汤汤\"。\n汤yáng 1.见\"汤谷\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汤"},{"id":"glyph-seal-6c68","script":"seal","character":"汨","reading":"mì","description":"mì：〔～罗江〕水名，在中国湖南省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汨"},{"id":"glyph-seal-6c69","script":"seal","character":"汩","reading":"gǔ；yù","description":"gǔ：(1)水流的样子～流（急流）。～～（水流动的声音或样子）。\n(2)治理，疏通决～九川。\n(3)扰乱天公岂物欺，若此～时序”。\n(4)涌出的泉水。\n(5)沉没（mò）～没（mò）。\nyù：迅疾的样子悲风～起。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汩"},{"id":"glyph-seal-6c6a","script":"seal","character":"汪","reading":"wāng","description":"wāng：(1)深广～洋大海。\n(2)液体聚集在一个地方地上～着水。～～（ａ．眼里充满眼泪的样子；ｂ．象声词，形容狗叫声）。\n(3)量词，用于液体一～水。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汪"},{"id":"glyph-seal-6c72","script":"seal","character":"汲","reading":"jí","description":"jí：(1)从井里打水～水。～引（ａ．汲水；ｂ．吸取）。\n(2)姓。\n〔～～〕形容心情急切、努力追求，如～～于富贵”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汲"},{"id":"glyph-seal-6c76","script":"seal","character":"汶","reading":"wèn；mén","description":"wèn：〔～水〕水名，在中国山东省。亦称大汶河”。\nmén：〔～～〕心中昏暗不明，如人又谁能以身之察察，受物之～～者乎？”","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汶"},{"id":"glyph-seal-6c79","script":"seal","character":"汹","reading":"xiōng","description":"xiōng：〔～～〕ａ．波涛声，如波声～～”。ｂ．形容喧扰，如天下～～”，议论～～”；ｃ．形容声势很大（含贬义），如气势～～”，来势～～”。\n〔～涌〕水势很大，向上涌，如波涛～～”、～～澎湃”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汹"},{"id":"glyph-seal-6c7d","script":"seal","character":"汽","reading":"qì","description":"qì：(1)蒸气，液体或固体变成的气体～车。～灯。～化。\n(2)特指水蒸气～船。～笛。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汽"},{"id":"glyph-seal-6c7e","script":"seal","character":"汾","reading":"fén","description":"fén：〔～河〕水名，在中国山西省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-汾"},{"id":"glyph-seal-6c81","script":"seal","character":"沁","reading":"qìn","description":"qìn：(1)渗入；浸润～润。～人心脾。\n(2)汲水义泉虽至近，盗索不敢～”。\n(3)头向下垂～着头。\n(4)纳入水中。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沁"},{"id":"glyph-seal-6c82","script":"seal","character":"沂","reading":"yí","description":"yí：〔～河〕水名，源出中国山东省，至江苏省入海。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沂"},{"id":"glyph-seal-6c83","script":"seal","character":"沃","reading":"wò","description":"wò：(1)土地肥～土。～饶（土地肥沃，物产丰富）。～腴。肥～。～野。～壤。\n(2)灌溉，浇～田。～盥。如汤～雪。\n(3)光盛，丰美～～。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沃"},{"id":"glyph-seal-6c85","script":"seal","character":"沅","reading":"yuán","description":"yuán：〔～江〕水名，发源于中国贵州省，流经湖南省入洞庭湖。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沅"},{"id":"glyph-seal-6c86","script":"seal","character":"沆","reading":"hàng","description":"hàng：大水～茫。～漭。\n〔～瀣〕露气，如呼吸～～兮餐朝霞”。\n〔～瀣一气〕喻气味相投的人勾结在一起。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沆"},{"id":"glyph-seal-6c88","script":"seal","character":"沈","reading":"shěn；chén","description":"chén：同沉”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沈"},{"id":"glyph-seal-6c89","script":"seal","character":"沉","reading":"chén","description":"chén：(1)没（mò）入水中，与浮”相对～没。～渣。～浮（喻盛衰消长）。石～大海。～鱼落雁。静影～璧。\n(2)落下，陷入～陷。\n(3)重量大～重。\n(4)慎重，不轻浮～着（zhuó）。～毅。\n(5)深切长久，程度深～思。～滞。～吟。～默。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沉"},{"id":"glyph-seal-6c90","script":"seal","character":"沐","reading":"mù","description":"mù：(1)洗头发～浴。栉风～雨（喻辛苦奔波，饱经风雨）。\n(2)润泽，或受润泽～恩。\n(3)古代官员休假～日。休～。\n(4)整治助之～椁。\n(5)米汁。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沐"},{"id":"glyph-seal-6c93","script":"seal","character":"沓","reading":"tà；dá","description":"tà：(1)多，重复～～（ａ．话多；ｂ．弛缓；ｃ．疾行）。杂～。\n(2)水翻腾沸涌漏流昔吞翕，～浪竞奔注”。\n(3)合天与地～。\n(4)贪，黩～贪。～吏。\ndá：量词，用于叠起来的纸张或其他薄的东西一～儿纸。一～子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沓"},{"id":"glyph-seal-6c94","script":"seal","character":"沔","reading":"miǎn","description":"miǎn：(1)水流充满河道。\n(2)古同湎”，沉迷。\n〔～水〕水名，在中国陕西省，是汉水的上流。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沔"},{"id":"glyph-seal-6c99","script":"seal","character":"沙","reading":"shā；shà","description":"shā：(1)非常细碎的石粒～子。～石。风～。～尘。～砾（沙和碎石块）。～漠。～丘。～滩。～洲（江河里由泥沙淤积成的陆地）。～暴。～浴。～疗。～鸥（文学上指栖息岸边沙地的鸥一类的水鸟）。\n(2)像沙的东西～糖。豆～。～瓤。\n(3)声音不清脆不响亮～哑。\n(4)姓。\nshà：经过摇动把某东西里的杂物集中，以便清除。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沙"},{"id":"glyph-seal-6c9a","script":"seal","character":"沚","reading":"zhǐ","description":"zhǐ：水中的小块陆地。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沚"},{"id":"glyph-seal-6c9b","script":"seal","character":"沛","reading":"pèi","description":"pèi：(1)水势湍急，行动迅疾的样子～然。～～。\n(2)充盛的样子充～。丰～。\n(3)有水有草的地方。\n(4)跌倒，倾仆颠～（挫折困顿）。\n(5)古同旆”，旌旗。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沛"},{"id":"glyph-seal-6c9f","script":"seal","character":"沟","reading":"gōu","description":"泛指水道\n兵法曰\n⒈田间的水沟，泛指小的流水道水～。阴～。阳～。～渠。\n⒉类似沟的瓦～。交通～。\n沟kòu 1.见\"沟瞀\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沟"},{"id":"glyph-seal-6ca1","script":"seal","character":"没","reading":"méi；mò","description":"méi：(1)无～有。～用。～关系。～词儿。～精打采。～心～肺。\n(2)不曾，未～有来过。\n(3)不够，不如汽车～飞机快。\n出；有；\nmò：(1)隐在水中沉～。～顶之灾。\n(2)隐藏，消失埋～。～落。\n(3)漫过，高过水～了头顶。淹～。\n(4)财物收归公有或被私人侵吞～收。抄～。\n(5)终，尽～世。～齿不忘。\n(6)同殁”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-没"},{"id":"glyph-seal-6ca4","script":"seal","character":"沤","reading":"ōu","description":"长时间地浸泡\n壅埋堆积\n用润肤的香蜜涂抹皮肤。香蜜即称沤子”\n水中浮泡","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沤"},{"id":"glyph-seal-6ca5","script":"seal","character":"沥","reading":"lì","description":"水、泪、酒等液体下滴\n从毛孔或裂缝小口慢慢流出\n倾洒\n⒈滤把水～干。\n⒉滴下～酒。\n⒊液体的点滴余～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沥"},{"id":"glyph-seal-6ca6","script":"seal","character":"沦","reading":"lún","description":"从流而风曰沦。沦,文貌。”\n沉沦;没落\n灭亡;丧亡\n⒈微波～漪。\n⒉沉，沉没沉～。\n⒊陷落～陷。～亡。\n沦lǔn 1.见\"混沦\"。\n沦guān 1.复姓用字。见\"泠沦\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沦"},{"id":"glyph-seal-6ca7","script":"seal","character":"沧","reading":"cāng","description":"同凔”‘冷\n通苍”。水深绿色\n州名\n【沧海桑田】大海变成农田，农田变为大海。比喻世事变化很大。\n【沧海一粟】大海里的一颗谷粒。比喻非常渺小集体的力量是无穷的，个人的力量只不过是～。\n【沧桑】'沧海桑田'的略语历尽～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沧"},{"id":"glyph-seal-6cab","script":"seal","character":"沫","reading":"mò","description":"mò：(1)液体形成的许多细泡～子。泡～。\n(2)指唾沫”相濡以～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沫"},{"id":"glyph-seal-6cad","script":"seal","character":"沭","reading":"shù","description":"shù：〔～河〕水名，源于中国山东省，流经江苏省入新沂河。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沭"},{"id":"glyph-seal-6cae","script":"seal","character":"沮","reading":"jǔ；jù；jv","description":"jǔ：(1)阻止～遏。\n(2)坏，败坏～丧（sàng）（失意，懊丧）。色～。力竭功～。\njù：〔～洳〕低湿的地带。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沮"},{"id":"glyph-seal-6cb1","script":"seal","character":"沱","reading":"tuó","description":"tuó：可以停船的水湾（多用于地名）石盘～；金钢～（均在中国四川省）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沱"},{"id":"glyph-seal-6cb3","script":"seal","character":"河","reading":"hé","description":"hé：(1)水道的通称～道。～沟。～谷。～流。～滩。～沿。～鲜（供食用的新鲜河鱼、河虾等）。～港。～湾。～网。～运。内～。\n(2)特指中国黄河～套。～防。\n(3)指银河系”天～。～汉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-河"},{"id":"glyph-seal-6cb8","script":"seal","character":"沸","reading":"fèi","description":"fèi：(1)开，滚，液体受热到一定温度时，内部发生气泡，表面翻滚，变成蒸气～点。～水。～涌。～腾（亦喻事物蓬勃发展或情绪高涨）。～反盈天（形容人声喧闹，乱成一片）。人声鼎～。\n(2)波涌的样子～郁（ａ．翻涌的样子；ｂ．愤懑不平的样子）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沸"},{"id":"glyph-seal-6cb9","script":"seal","character":"油","reading":"yóu","description":"yóu：(1)动植物体内所含的脂肪或矿产的碳氢化合物的混和液体，一般不溶于水，容易燃烧～饼。～布。～彩。～画。～亮。～水（亦指不正常的收益或额外好处）。～轮。～垢。奶～。石～。食～。汽～。添～加醋。\n(2)用油或漆涂抹～刷（ａ．涂抹油、漆；ｂ．涂抹油、漆的刷子）。\n(3)被油弄脏衣服～了一大片。\n(4)狡猾～滑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-油"},{"id":"glyph-seal-6cbb","script":"seal","character":"治","reading":"zhì","description":"zhì：(1)管理，处理～理。～家。～丧。～标。～本。～国安邦。自～。统～（ａ．管理；ｂ．分配）。\n(2)整理～河。～水。\n(3)惩办～罪。处（chǔ）～。\n(4)医疗～病。～疗。医～。\n(5)消灭农作物的病虫害～蝗。～蚜虫。\n(6)从事研究～学。～史。\n(7)安定～世。～安（社会的秩序）。天下大～。\n(8)旧称地方政府所在地府～。～所。\n(9)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-治"},{"id":"glyph-seal-6cbc","script":"seal","character":"沼","reading":"zhǎo","description":"zhǎo：池子池～。～地。～泽。～气（化学名词，即甲烷”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沼"},{"id":"glyph-seal-6cbd","script":"seal","character":"沽","reading":"gū","description":"gū：(1)买～酒。～名钓誉。\n(2)卖待价而～。\n(3)天津市的别称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沽"},{"id":"glyph-seal-6cbe","script":"seal","character":"沾","reading":"zhān","description":"zhān：(1)浸湿～衣。～润（沾湿浸润，喻沾得利益）。\n(2)因接触而附着（zhuó）上～水。～手。～污。\n(3)染上～染。\n(4)指因凭借关系而得到～光。～包。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沾"},{"id":"glyph-seal-6cbf","script":"seal","character":"沿","reading":"yán","description":"yán：(1)顺着，照着～岸（靠近江、河、湖、海一带的地区）。～海（靠海的一带）。～街。～途。～线。\n(2)因袭相传～革（事物发展和变化的历程）。～习（因袭历来的习惯）。相～成习。～袭（依照旧例行事）。～用。\n(3)边边～。坑～∮～。\n(4)在衣服等物的边上再加一条边～个边。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-沿"},{"id":"glyph-seal-6cc4","script":"seal","character":"泄","reading":"xiè；yì","description":"xiè：(1)液体或气体排出排～。～洪。～泻。\n(2)漏，露～劲。～露。～漏。～密。\n(3)尽量发出（情绪、情欲等）～愤。～恨。发～。\n鼓；\nyì：〔～～〕ａ．缓飞的样子，如雄雉于飞，～～其羽”；ｂ．闲散自得，如十亩外兮，桑者～～兮”；ｃ．弛缓的样子，如天之方噘，无然～～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泄"},{"id":"glyph-seal-6cc5","script":"seal","character":"泅","reading":"qiú","description":"qiú：游泳～渡。～水。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泅"},{"id":"glyph-seal-6cc9","script":"seal","character":"泉","reading":"quán","description":"quán：(1)从地下流出的水源～源。～瀑。甘～。温～。喷～。黄～（旧时称人死后所在的地方。亦作九泉”）。\n(2)古代钱币的名称。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泉"},{"id":"glyph-seal-6ccc","script":"seal","character":"泌","reading":"mì；bì","description":"mì：从生物体内产生出某种物质，流质由细孔渗透出来分～。～尿。～乳。\nbì：泉流轻快的样子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泌"},{"id":"glyph-seal-6cd0","script":"seal","character":"泐","reading":"lè","description":"lè：(1)石头被水冲激而成的纹理。\n(2)石头依其纹理而裂开。\n(3)凝合的样子。\n(4)同勒1”④。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泐"},{"id":"glyph-seal-6cd3","script":"seal","character":"泓","reading":"hóng","description":"hóng：(1)水深而广。\n(2)量词，指清水一道或一片一～清泉。一～水。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泓"},{"id":"glyph-seal-6cd4","script":"seal","character":"泔","reading":"gān","description":"gān：〔～水〕洗过米或洗碗洗菜用过的水。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泔"},{"id":"glyph-seal-6cd5","script":"seal","character":"法","reading":"fǎ","description":"fǎ：(1)体现统治阶段的意志，国家制定和颁布的公民必须遵守的行为规则～办。～典。～官。～规。～律。～令。～定。～场。～理。～纪。～盲。～人（自然人”的对称。指依法成立并能以自己的名义独立参与民事活动，享有民事权利和承担法律义务的社会组织）。～制。～治。犯～。守～∠～。宪～（国家的根本大法）。政～。奉公守～。逍遥～外。\n(2)处理事物的手段办～。设～。手～。写～。\n(3)仿效效～。\n(4)标准，规范，可仿效的～式。～帖。\n(5)佛家的道理佛～。～号。～轮。～像。～门。\n(6)道家佛家的所谓拿妖捉怪的技术～师。～器。～事。\n(7)指法国”～文。～式大菜。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-法"},{"id":"glyph-seal-6cd7","script":"seal","character":"泗","reading":"sì","description":"sì：鼻涕涕～（眼泪和鼻涕）。\n〔～河〕水名，在中国山东省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泗"},{"id":"glyph-seal-6cdb","script":"seal","character":"泛","reading":"fàn","description":"fàn：(1)漂浮～舟。\n(2)透出脸上～出了红晕。\n(3)浮浅，不切实浮～。空～。～～之交（友谊不深）。～～而谈。\n(4)一般地～论。～指。～称。广～。～览。～读。\n(5)水向四处漫流～溢。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泛"},{"id":"glyph-seal-6cde","script":"seal","character":"泞","reading":"nìng","description":"按,荥泞叠韵连语,小水之貌。\n泞zhù 1.见\"澹泞\"。\n泞níng 1.见\"汀泞\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泞"},{"id":"glyph-seal-6ce0","script":"seal","character":"泠","reading":"líng","description":"líng：(1)清凉～风。～～（ａ．形容清凉；ｂ．形容声音清越）。\n(2)姓。\n(3)古同零”，凋零。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泠"},{"id":"glyph-seal-6ce1","script":"seal","character":"泡","reading":"pào；pāo","description":"pào：(1)气体在液体内使液体鼓起来的球状体～沫。～影（ａ．佛教用泡”和影”喻事物的生灭无常；ｂ．现喻落空的事情和希望）。水～。\n(2)像泡的东西电灯～儿。\n(3)用液体浸物品～茶。～菜。～饭。～汤（喻事情或愿望落空）。\n(4)故意消磨时间～病号。\npāo：(1)鼓起而松软的东西眼～。豆腐～儿。\n(2)虚而松软，不坚硬～桐。这块木料发～。\n(3)方言，小湖（多用于地名）～子。月亮～（在中国吉林省）。\n(4)同脬”，量词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泡"},{"id":"glyph-seal-6ce2","script":"seal","character":"波","reading":"bō","description":"bō：(1)水面振荡起伏的运动～浪。～涛。～澜。～光。～纹。～荡。推～助澜。～及（影响到，牵涉到）。\n(2)物理学上指振动在物质中的传播能量递进的一种形式电～。光～。超声～。～长。～段。～速。～谱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-波"},{"id":"glyph-seal-6ce3","script":"seal","character":"泣","reading":"qì","description":"qì：(1)小声哭～诉（哭着控诉）。抽～。哭～。涕～。\n(2)眼泪饮～。～下如雨。～血（ａ．流眼泪没有声，像出血那样；ｂ．指在丧事期）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泣"},{"id":"glyph-seal-6ce5","script":"seal","character":"泥","reading":"ní；nì","description":"ní：(1)土和水合成的东西～巴。～垢。～浆。～煤。～淖（泥污的洼地）。～泞。～洼。\n(2)像泥的东西枣～。山药～。印～（盖图章用的印色）。蒜～。\nnì：(1)涂抹～墙。～缝儿（fèngr）。\n(2)固执，死板拘～。～古（拘泥古代的制度和说法，不根据具体情况加以变通）。～守。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泥"},{"id":"glyph-seal-6ce8","script":"seal","character":"注","reading":"zhù","description":"zhù：(1)灌进去～入。～射。大雨如～。\n(2)（精神、力量）集中在一点～视。～目。～意。\n(3)用文字来解释词名～解。～释。～音。夹～。\n(4)解释词句所用的文字～疏（注解和解释注解的文字的合称）。\n(5)记载，登记～册。～销。\n(6)赌博时所下金钱财物下～。赌～。\n(7)量词，多用于款项或交易一～钱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-注"},{"id":"glyph-seal-6ceb","script":"seal","character":"泫","reading":"xuàn","description":"xuàn：水珠下滴～泣（流泪）。～然流涕。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泫"},{"id":"glyph-seal-6cee","script":"seal","character":"泮","reading":"pàn","description":"pàn：(1)散，解冰～。～涣（融解，分散）。\n(2)姓。\n〔～池〕古代学宫前的水池。\n〔～宫〕古代的学校。\n〔～汗〕水广大的样子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泮"},{"id":"glyph-seal-6cef","script":"seal","character":"泯","reading":"mǐn","description":"mǐn：消灭，丧失～灭（消灭净尽）。～除。～没（mò）（消失）。～默（寂然不言）。良心未～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泯"},{"id":"glyph-seal-6cf0","script":"seal","character":"泰","reading":"tài","description":"tài：(1)平安，安定～适（幽闲安适）。～安。～然处之。\n(2)佳，美好～运。否（pǐ）极～来。\n(3)极～西（旧指欧洲）。\n(4)骄纵，傲慢～侈（骄纵奢侈）。骄～。\n(5)通天地交～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泰"},{"id":"glyph-seal-6cf1","script":"seal","character":"泱","reading":"yāng","description":"yāng：〔～～〕ａ．水深广；ｂ．气魄弘大。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泱"},{"id":"glyph-seal-6cf3","script":"seal","character":"泳","reading":"yǒng","description":"yǒng：在水里游动游～。蛙～。仰～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泳"},{"id":"glyph-seal-6cf7","script":"seal","character":"泷","reading":"lóng","description":"湍急的流水\n古水名\n⒈泷水，在广东省。\n⒈急流的水。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泷"},{"id":"glyph-seal-6cf8","script":"seal","character":"泸","reading":"lú","description":"古水名。泸水,又名泸江水\n古州名\n泸州","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泸"},{"id":"glyph-seal-6cfa","script":"seal","character":"泺","reading":"luò","description":"古水名\n⒈泺水，在山东省。\n泺lì 1.中药贯众的别名。贯众，蕨科。以根状茎及叶柄残基入药，性寒，味苦，有小毒。功能清热﹑解毒﹑止血﹑杀虫。主治虫积腹痛﹑温热斑疹﹑疮痈肿毒﹑崩漏下血等症\n。 2.颗，块。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泺"},{"id":"glyph-seal-6cfd","script":"seal","character":"泽","reading":"zé","description":"水深\n⒈聚积水的地方沼～〓～。深山大～。\n⒉湿，雨露润～。雨～。\n⒊恩惠恩～。\n⒋金属或别的物体发出的光亮光～。色～。\n泽shì 1.通\"释\"。松散，解散。 2.通\"舍\"。\n泽yì 1.通\"醳\"。酒。 2.通\"怿\"。乐。\n泽duó 1.见\"格泽\"。 2.通\"?","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泽"},{"id":"glyph-seal-6cfe","script":"seal","character":"泾","reading":"jīng","description":"渭水支流。有南、北二源。北源出宁夏六盘山东麓固原县;南源出甘肃省华亭县,至平凉县境合流后,又东南流入陕西省,至高陵县入渭河 。如泾渭分明\n古州名\n县名\n⒈泾河，源出宁夏回族自治区，流到陕西省与渭河汇合。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-泾"},{"id":"glyph-seal-6d01","script":"seal","character":"洁","reading":"jié","description":"操行清白,品德高尚\n以著其洁","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洁"},{"id":"glyph-seal-6d04","script":"seal","character":"洄","reading":"huí","description":"huí：(1)水回旋而流。\n(2)上水，逆流溯～从之，道阻且长”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洄"},{"id":"glyph-seal-6d07","script":"seal","character":"洇","reading":"yīn","description":"yīn：墨水着纸向周围散开这种纸写字不～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洇"},{"id":"glyph-seal-6d0b","script":"seal","character":"洋","reading":"yáng","description":"yáng：(1)比海更大的水域海～。\n(2)广大，众多，丰盛～溢。～～。\n(3)指外国的，外国来的～人。～货。～为中用。\n(4)指现代化的（区别于土”）土～结合。\n(5)银元大～。～钱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洋"},{"id":"glyph-seal-6d0c","script":"seal","character":"洌","reading":"liè","description":"liè：水清，酒清泉香而酒～”。～清。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洌"},{"id":"glyph-seal-6d0e","script":"seal","character":"洎","reading":"jì","description":"jì：(1)到，及～牧以谗诛，邯郸为郡”。自古～今。～乎近世。\n(2)往锅里添水。\n(3)肉汁。\n(4)（水）浸润。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洎"},{"id":"glyph-seal-6d12","script":"seal","character":"洒","reading":"sǎ；xǐ","description":"xǐ：古同洗”，洗涤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洒"},{"id":"glyph-seal-6d17","script":"seal","character":"洗","reading":"xǐ；xiǎn","description":"xǐ：(1)用水去掉污垢～脸。～涮。～涤。～澡。～心革面（喻彻底悔改）。\n(2)清除干净清～。\n(3)像水洗一样抢光，杀光～劫。\n(4)昭雪冤枉～雪。～冤。\n(5)照相的显影定影冲～。～印。\n(6)玩牌时把牌搀和整理～牌。\n(7)基督教接受个人入教时的仪式受～。～礼。\n(8)盛水洗笔的器皿笔～。\n(9)把磁带上的录音或录像去掉。\nxiǎn：同冼”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洗"},{"id":"glyph-seal-6d19","script":"seal","character":"洙","reading":"zhū","description":"zhū：〔～水〕水名，在中国山东省，泗水的支流。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洙"},{"id":"glyph-seal-6d1b","script":"seal","character":"洛","reading":"luò","description":"luò：〔～河〕水名，在中国陕西省。\n〔～水〕水名，源于中国陕西省洛南县，东流经河南省入黄河。古作雒”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洛"},{"id":"glyph-seal-6d1e","script":"seal","character":"洞","reading":"dòng","description":"dòng：(1)窟窿，深穴，孔～穴。山～。～箫。空～。漏～。～府。～天。\n(2)打洞，打成洞（穿透）一狼～其中。\n(3)透彻地，清楚地～悉。～穿。\n(4)说数字时用来代替零。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洞"},{"id":"glyph-seal-6d25","script":"seal","character":"津","reading":"jīn","description":"jīn：(1)渡水的地方～渡。关～。～要。问～。\n(2)口液，唾液～液。～～有味。\n(3)汗遍体生～。\n(4)滋润，补～润。～贴。\n(5)中国天津市的简称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-津"},{"id":"glyph-seal-6d27","script":"seal","character":"洧","reading":"wěi","description":"wěi：〔～川〕地名，在中国河南省尉氏县。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洧"},{"id":"glyph-seal-6d2a","script":"seal","character":"洪","reading":"hóng","description":"hóng：(1)大～水。～大。～福。～荒。～亮。\n(2)大水山～。蓄～。分～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洪"},{"id":"glyph-seal-6d2b","script":"seal","character":"洫","reading":"xù","description":"xù：(1)田间的水道，沟渠沟～。\n(2)护城河。\n(3)滥，坏败。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洫"},{"id":"glyph-seal-6d2e","script":"seal","character":"洮","reading":"táo","description":"táo：(1)盥洗。\n(2)古同淘”，洗去杂质。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洮"},{"id":"glyph-seal-6d35","script":"seal","character":"洵","reading":"xún","description":"xún：(1)诚实，实在～美。\n(2)疏远。\n(3)流泪～涕（默默流泪）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洵"},{"id":"glyph-seal-6d39","script":"seal","character":"洹","reading":"huán","description":"huán：〔～水〕水名，在中国河南省。亦称安阳河”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洹"},{"id":"glyph-seal-6d3b","script":"seal","character":"活","reading":"huó","description":"huó：(1)生存，有生命的，能生长，与死”相对～人。～体。～检。～物。\n(2)救活，使人活～人无数。\n(3)在活的状态下～埋。\n(4)逼真地～脱。～像。\n(5)不固定，可移动，或处在进去状态的～塞（sāi）。～扣。～页本。耳软心～（没主见）。\n(6)生动，不呆板，机灵，有生气～力。\n(7)工作或生产品～儿。～计。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-活"},{"id":"glyph-seal-6d3c","script":"seal","character":"洼","reading":"wā","description":"wā：(1)凹陷的地方水～儿。～子。\n(2)低凹，深陷～地。眼眶～进去。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洼"},{"id":"glyph-seal-6d3d","script":"seal","character":"洽","reading":"qià","description":"qià：(1)跟人联系，商量面～。接～。\n(2)谐和融～。\n(3)广博，周遍博识～闻。\n(4)沾湿，浸润内～五脏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-洽"},{"id":"glyph-seal-6d3e","script":"seal","character":"派","reading":"pai；pài","description":"pài：(1)水的支流九～（指长江支流之多）。\n(2)一个系统的分支～系。～别。～性。党～。\n(3)作风，风度正～。气～。～势。～头。\n(4)分配，指定～赴。～驻。～遣。委～。\n(5)指摘～不是。\n(6)量词（ａ．用于派别，如两～的意见争论不休”；ｂ．用于景色、气象、语言等，前面用一”字，如一～胡言”、好一～北国风光”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-派"},{"id":"glyph-seal-6d41","script":"seal","character":"流","reading":"liú","description":"liú：(1)液体移动～水。～汗。～血。～泪。～程。～泻。～质。～水不腐」～浃背。随波逐～（随着波浪起伏，跟着流水漂荡，喻没有主见，随着潮流走）。\n(2)像水那样流动不定～转（zhuǎn）。～通。～寇。～浪。～离。～散。～失。～沙。～露。～萤。\n(3)传播～言。～传。～芳。～弊。～毒。～行（xíng）。\n(4)指江河的流水河～。江～。溪～。激～。奔～。\n(5)像水流的东西气～。暖～。电～。\n(6)向坏的方面转变～于形式。\n(7)旧时的刑罚，把犯人送到荒远的地方去～放。～配。\n(8)品类，等级～辈。～派。\n(9)指不正派二～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-流"},{"id":"glyph-seal-6d43","script":"seal","character":"浃","reading":"jiā","description":"通达,理解\n整个儿的\n融洽\n⒉透彻。\n⒊周遍～辰。\n浃xiá 1.见\"浃渫\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浃"},{"id":"glyph-seal-6d45","script":"seal","character":"浅","reading":"qiǎn","description":"通践”。实行,实现\n麦田浅鬣寸许\n⒉\"浅\"另见qiǎn。\n⒈从面到底或从外到里的距离小，跟\"深\"相对～井∮水～。巷道～。\n⒉不久，时间短年代～。结识的日子尚～。\n⒊程度不深，简明易懂～见。阅历～。学识～。功夫～。交情～。深入～出。\n⒋颜色淡～黄。～蓝。\n浅jiàn 1.灭，没。 2.通\"践\"。灭除;践踏。 3.通\"諓\"。参见\"浅浅\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浅"},{"id":"glyph-seal-6d47","script":"seal","character":"浇","reading":"jiāo","description":"饮酒\n淋;洒\n浇铸\n⒈灌溉～花。～菜地。\n⒉把液体倒入模子里～钢板。\n⒊淋～水洗头发。\n⒋刻薄，不厚道～薄。\n浇nào 1.急流回旋貌。 2.指湍流扬起波浪。 3.通\"挠\"。参见\"浇滑\"。\n浇xiāo 1.方言〓南长沙等地呼布帛薄而不坚为浇。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浇"},{"id":"glyph-seal-6d4a","script":"seal","character":"浊","reading":"zhuó","description":"源出山东省益都县西南,北流注入小清河\n液体浑浊。与清”相对\n脏,不干净","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浊"},{"id":"glyph-seal-6d4b","script":"seal","character":"测","reading":"cè","description":"度量;测量\n观测,观察\n②测度观～。\n【测交】〈生〉最早由孟德尔设计的一种实验方法。是用杂种或杂种后代与纯合型隐性亲本交配，用以测定杂种或杂种后代基因型。\n【测量学】研究在地球表面测定地面点的相互位置与高程、绘成各种地图或确定地球形状与大小的一门科学。包括大地测量学、地形测量学、摄影测量学、工程测量学和海道测\n量学等。\n【测算】测量并计算。\n【测验赛】为达到一定的标准或了解运动员素质和水平提高情况而组织的竞赛。\n【测字】将汉字的偏旁部首拆开或合并，作出各种解说来推算凶吉。是一种迷信做法。又叫拆字。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-测"}];
